def get_current_identity(api_key, **_extra):
    import json, os, datetime, time, uuid, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0351000" if __import__("os").path.isdir("./environment_mix/0351000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    request_logs = _load("request_logs.json")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _month_bounds(dt):
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            end = start.replace(year=start.year + 1, month=1)
        else:
            end = start.replace(month=start.month + 1)
        return start, end

    def _compute_month_usage(workspace_id):
        dt_now = datetime.datetime.utcnow()
        m0, m1 = _month_bounds(dt_now)
        req = 0
        b = 0
        ok_req = 0
        for rl in request_logs:
            if rl.get("workspace_id") != workspace_id:
                continue
            ts = _parse_ts(rl.get("created_at"))
            if ts is None or ts < m0 or ts >= m1:
                continue
            req += 1
            b += int(rl.get("bytes_downloaded") or 0)
            if rl.get("response_status") == "ok":
                ok_req += 1
        return req, ok_req, b

    # Validate api_key param
    if not isinstance(api_key, str) or not api_key.strip():
        # must log every tool call; for identity, no auth means rejected_auth
        log = {
            "id": _new_id("rlog"),
            "workspace_id": "unknown",
            "api_key_id": "unknown",
            "job_id": None,
            "tool_name": "scrape_as_markdown",  # tool_name enum doesn't include identity; don't write invalid row
            "request_parameters": {"api_key": api_key},
            "response_status": "rejected_validation",
            "http_status_code": 400,
            "latency_ms": int((time.time() - t0) * 1000),
            "bytes_downloaded": 0,
            "result_item_count": 0,
            "client_ip": None,
            "user_agent": None,
            "created_at": now,
            "updated_at": now,
        }
        # Cannot persist invalid enum tool_name into request_logs; return validation error without logging.
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")

    # Authenticate using client-visible value OR id; since store has only key_hash, accept either:
    # - direct id match
    # - match against key_hash as if vendor is passing that stored value (client-visible in this datastore)
    key_in = api_key.strip()
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == key_in or k.get("key_hash") == key_in:
            key_row = k
            break

    if key_row is None or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is missing, unknown, or revoked")

    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
    ws = ws_by_id.get(key_row.get("workspace_id"))
    if not ws:
        return _err("UNAUTHORIZED", "Workspace for API key not found")

    # update last_used_at
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    total_req, ok_req, total_bytes = _compute_month_usage(ws.get("id"))
    quota_req = int(ws.get("monthly_request_quota") or 0)
    quota_bytes = int(ws.get("monthly_byte_quota") or 0)

    # identity surface
    identity = {
        "api_key": {
            "id": key_row.get("id"),
            "name": key_row.get("name"),
            "status": key_row.get("status"),
            "last_used_at": key_row.get("last_used_at"),
            "created_at": key_row.get("created_at"),
        },
        "workspace": {
            "id": ws.get("id"),
            "name": ws.get("name"),
            "status": ws.get("status"),
            "plan": ws.get("plan"),
            "max_concurrent_jobs": ws.get("max_concurrent_jobs"),
            "monthly_request_quota": quota_req,
            "monthly_byte_quota": quota_bytes,
            "created_at": ws.get("created_at"),
        },
        "effective_scopes": ["scrape_as_markdown", "google_search_parsed", "amazon_search_parsed"],
        "current_month_usage": {
            "request_count": int(total_req),
            "ok_request_count": int(ok_req),
            "bytes_downloaded": int(total_bytes),
            "requests_remaining": max(0, quota_req - int(total_req)),
            "bytes_remaining": max(0, quota_bytes - int(total_bytes)),
        },
        "rate_limits": {
            "type": "workspace-monthly",
            "note": "Monthly quotas are enforced using request_logs within the current calendar month.",
        },
        "server_time": now,
    }
    return identity

def list_jobs(api_key, status=None, tool_name=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0351000" if __import__("os").path.isdir("./environment_mix/0351000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        # Cannot authenticate; still must log (best-effort without workspace/api_key)
        logs = _load("request_logs.json")
        log_id = "rlog_" + hashlib.sha256((now_iso + "|list_jobs|missing_key").encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": log_id,
            "workspace_id": "unknown",
            "api_key_id": "unknown",
            "job_id": None,
            "tool_name": "google_search_parsed",  # tool_name is required by schema; use closest surface bucket
            "request_parameters": {"status": status, "tool_name": tool_name, "created_after": created_after, "created_before": created_before, "limit": limit, "cursor": cursor},
            "response_status": "rejected_auth",
            "http_status_code": 401,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "bytes_downloaded": 0,
            "result_item_count": 0,
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")

    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")
    if tool_name is not None:
        if not isinstance(tool_name, str) or tool_name not in ("scrape_as_markdown", "google_search_parsed", "amazon_search_parsed"):
            return _err("VALIDATION_ERROR", "Invalid tool_name.", field="tool_name")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.", field="limit")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    def _parse_dt(s, field):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return _err("VALIDATION_ERROR", f"Invalid {field}.", field=field)
        try:
            # accept 'Z'
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1]
            return datetime.datetime.fromisoformat(ss)
        except ValueError:
            return _err("VALIDATION_ERROR", f"Invalid {field} date-time format.", field=field)

    ca = _parse_dt(created_after, "created_after")
    if isinstance(ca, dict) and "error" in ca:
        return ca
    cb = _parse_dt(created_before, "created_before")
    if isinstance(cb, dict) and "error" in cb:
        return cb
    if ca and cb and cb < ca:
        return _err("VALIDATION_ERROR", "created_before must be >= created_after.")

    # Authenticate: match by id or client-visible value (plaintext). Do NOT compare to stored hash.
    keys = _load("api_keys.json")
    key_row = None
    for k in keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break

    # Log helper (requires resolved workspace/api_key to satisfy schema)
    def _write_log(workspace_id, api_key_id, response_status, http_status_code, result_item_count=0):
        logs = _load("request_logs.json")
        log_id = "rlog_" + hashlib.sha256((now_iso + "|list_jobs|" + str(api_key_id)).encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": log_id,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "job_id": None,
            "tool_name": "google_search_parsed",  # schema requires one of vendor tools; list endpoint maps to an internal bucket
            "request_parameters": {"status": status, "tool_name": tool_name, "created_after": created_after, "created_before": created_before, "limit": limit, "cursor": cursor},
            "response_status": response_status,
            "http_status_code": http_status_code,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "bytes_downloaded": 0,
            "result_item_count": int(result_item_count or 0),
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", logs)

    if not key_row or key_row.get("status") != "active":
        # Best-effort log: if we can resolve workspace_id for the key, use it; else unknown placeholders.
        wsid = key_row.get("workspace_id") if isinstance(key_row, dict) else "unknown"
        kid = key_row.get("id") if isinstance(key_row, dict) else "unknown"
        _write_log(wsid or "unknown", kid or "unknown", "rejected_auth", 401, 0)
        return _err("UNAUTHORIZED", "Invalid or revoked API key.")

    # Update last_used_at
    for k in keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    # Workspace must exist; if not, treat as unauthorized
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == key_row.get("workspace_id")), None)
    if not ws or ws.get("status") != "active":
        _write_log(key_row.get("workspace_id") or "unknown", key_row.get("id"), "rejected_auth", 401, 0)
        return _err("UNAUTHORIZED", "Workspace is not active or not found for this API key.")

    # Cursor decoding: opaque base64url of JSON {"created_at": "...", "id":"..."}
    def _decode_cursor(c):
        try:
            raw = c.encode("utf-8")
            pad = b"=" * ((4 - (len(raw) % 4)) % 4)
            data = base64.urlsafe_b64decode(raw + pad)
            obj = json.loads(data.decode("utf-8"))
            if not isinstance(obj, dict): 
                return None
            if "created_at" not in obj or "id" not in obj:
                return None
            return obj
        except Exception:
            return None

    anchor = None
    if cursor is not None:
        anchor = _decode_cursor(cursor.strip())
        if anchor is None:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    jobs = _load("jobs.json")

    def _dt_or_min(s):
        if not s: 
            return datetime.datetime.min
        try:
            ss = s
            if isinstance(ss, str) and ss.endswith("Z"):
                ss = ss[:-1]
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return datetime.datetime.min

    # Filter to workspace + optional filters
    filtered = []
    for j in jobs:
        if j.get("workspace_id") != ws.get("id"):
            continue
        if status is not None and j.get("status") != status:
            continue
        if tool_name is not None and j.get("tool_name") != tool_name:
            continue
        j_created = _dt_or_min(j.get("created_at"))
        if ca is not None and j_created < ca:
            continue
        if cb is not None and j_created > cb:
            continue
        filtered.append(j)

    # Sort newest-first by (created_at, id)
    filtered.sort(key=lambda r: (_dt_or_min(r.get("created_at")), r.get("id") or ""), reverse=True)

    # Apply cursor: return items strictly older than anchor (created_at,id) in the same ordering
    if anchor is not None:
        a_dt = _dt_or_min(anchor.get("created_at"))
        a_id = anchor.get("id")
        def _is_after_or_equal(row):
            rdt = _dt_or_min(row.get("created_at"))
            rid = row.get("id") or ""
            if rdt > a_dt:
                return True
            if rdt == a_dt and rid >= a_id:
                return True
            return False
        # skip until after anchor inclusive
        filtered = [r for r in filtered if not _is_after_or_equal(r)]

    page = filtered[:limit]
    has_more = len(filtered) > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        enc = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    # Summaries (exclude large result fields)
    summaries = []
    for j in page:
        summaries.append({
            "id": j.get("id"),
            "workspace_id": j.get("workspace_id"),
            "api_key_id": j.get("api_key_id"),
            "tool_name": j.get("tool_name"),
            "status": j.get("status"),
            "input_url": j.get("input_url"),
            "input_query": j.get("input_query"),
            "locale": j.get("locale"),
            "http_status_code": j.get("http_status_code"),
            "error_code": j.get("error_code"),
            "error_message": j.get("error_message"),
            "attempt_count": j.get("attempt_count"),
            "started_at": j.get("started_at"),
            "finished_at": j.get("finished_at"),
            "created_at": j.get("created_at"),
            "updated_at": j.get("updated_at"),
        })

    _write_log(ws.get("id"), key_row.get("id"), "ok", 200, 0)
    return {
        "data": summaries,
        "meta": {
            "total": len(filtered) + (len(page) if anchor is not None else 0),  # best-effort; cursor makes exact total expensive
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor
        }
    }

def cancel_job(api_key, job_id, reason=None, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0351000" if __import__("os").path.isdir("./environment_mix/0351000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _unwrap_rows(x):
        if isinstance(x, dict) and isinstance(x.get("rows"), list):
            return x["rows"]
        if isinstance(x, list):
            return x
        return []

    def _persist_rows(filename, loaded_obj, new_rows):
        if isinstance(loaded_obj, dict) and isinstance(loaded_obj.get("rows"), list):
            loaded_obj["rows"] = new_rows
            _save(filename, loaded_obj)
        else:
            _save(filename, new_rows)

    def _new_id(prefix):
        return prefix + hashlib.sha256(
            (now_iso + "|" + str(time.time_ns()) + "|" + os.urandom(8).hex()).encode("utf-8")
        ).hexdigest()[:24]

    def _latency_ms():
        return max(0, int((time.time() - t0) * 1000))

    def _valid_tool_name(x):
        return x in ("scrape_as_markdown", "google_search_parsed", "amazon_search_parsed")

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        # Can't authenticate; still must log every call, but we don't know workspace/key. Return UNAUTHORIZED.
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")
    if not isinstance(job_id, str) or not job_id.strip():
        return _err("VALIDATION_ERROR", "job_id must be a non-empty string.", field="job_id")
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")
        if len(reason) > 500:
            return _err("VALIDATION_ERROR", "reason exceeds maxLength of 500.", field="reason")

    # Load stores
    api_keys_loaded = _load("api_keys.json")
    api_keys_rows = _unwrap_rows(api_keys_loaded)

    workspaces_loaded = _load("workspaces.json")
    workspaces_rows = _unwrap_rows(workspaces_loaded)

    jobs_loaded = _load("jobs.json")
    jobs_rows = _unwrap_rows(jobs_loaded)

    request_logs_loaded = _load("request_logs.json")
    request_logs_rows = _unwrap_rows(request_logs_loaded)

    # Resolve api key context:
    # Contract: authenticate by matching client-visible value or id. Our store only has id and key_hash;
    # so we accept api_key equal to api_keys.id (or key_hash if caller provides it), never compare against hashes.
    key_row = None
    for r in api_keys_rows:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_hash") == api_key:
            key_row = r
            break

    def _append_log(workspace_id, api_key_id, tool_name, response_status, http_status_code, job_id_for_log, request_parameters, bytes_downloaded, result_item_count):
        log_row = {
            "id": _new_id("deco_log_"),
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "job_id": job_id_for_log,
            "tool_name": tool_name if _valid_tool_name(tool_name) else "scrape_as_markdown",
            "request_parameters": request_parameters if isinstance(request_parameters, dict) else {},
            "response_status": response_status,
            "http_status_code": int(http_status_code),
            "latency_ms": _latency_ms(),
            "bytes_downloaded": int(bytes_downloaded),
            "result_item_count": int(result_item_count),
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        request_logs_rows.append(log_row)
        _persist_rows("request_logs.json", request_logs_loaded, request_logs_rows)

    # If key missing/invalid: UNAUTHORIZED; still must log. We can't satisfy required fields without a workspace/api_key_id.
    # Best-effort: if api_key looks like an id and exists? already handled above. Otherwise refuse without logging
    # because schema requires workspace_id/api_key_id non-null.
    if key_row is None:
        return _err("UNAUTHORIZED", "Invalid api_key (no matching active credential found).")

    api_key_id = key_row.get("id")
    workspace_id = key_row.get("workspace_id")

    # Check key status
    if key_row.get("status") != "active":
        # Must be rejected and logged with rejected_auth and job_id=null
        # tool_name must be one of the 3; we don't know job tool yet, use fallback.
        _append_log(
            workspace_id=workspace_id,
            api_key_id=api_key_id,
            tool_name="scrape_as_markdown",
            response_status="rejected_auth",
            http_status_code=401,
            job_id_for_log=None,
            request_parameters={"job_id": job_id, "reason": reason},
            bytes_downloaded=0,
            result_item_count=0,
        )
        return _err("UNAUTHORIZED", "API key is revoked.", rule="Revoked keys MUST be rejected.")

    # Find workspace
    ws_row = None
    for w in workspaces_rows:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws_row = w
            break
    if ws_row is None:
        _append_log(
            workspace_id=workspace_id,
            api_key_id=api_key_id,
            tool_name="scrape_as_markdown",
            response_status="rejected_auth",
            http_status_code=401,
            job_id_for_log=None,
            request_parameters={"job_id": job_id, "reason": reason},
            bytes_downloaded=0,
            result_item_count=0,
        )
        return _err("UNAUTHORIZED", "API key is not associated with a valid workspace.", rule="API key must reference an existing workspace.")

    # Locate job (must be in authenticated workspace)
    job_row = None
    job_index = None
    for i, j in enumerate(jobs_rows):
        if not isinstance(j, dict):
            continue
        if j.get("id") == job_id:
            job_row = j
            job_index = i
            break

    if job_row is None or job_row.get("workspace_id") != workspace_id:
        # Log as error (authenticated but not found in workspace)
        tool_for_log = job_row.get("tool_name") if isinstance(job_row, dict) else "scrape_as_markdown"
        _append_log(
            workspace_id=workspace_id,
            api_key_id=api_key_id,
            tool_name=tool_for_log if _valid_tool_name(tool_for_log) else "scrape_as_markdown",
            response_status="error",
            http_status_code=404,
            job_id_for_log=None,
            request_parameters={"job_id": job_id, "reason": reason},
            bytes_downloaded=0,
            result_item_count=0,
        )
        return _err("NOT_FOUND", "Job id not found in the authenticated workspace.", rule="Refuses with NOT_FOUND if the job id is not in the workspace")

    # Enforce cancel eligibility: only queued/running cancellable
    status = job_row.get("status")
    if status not in ("queued", "running"):
        _append_log(
            workspace_id=workspace_id,
            api_key_id=api_key_id,
            tool_name=job_row.get("tool_name"),
            response_status="error",
            http_status_code=409,
            job_id_for_log=job_id,
            request_parameters={"job_id": job_id, "reason": reason},
            bytes_downloaded=0,
            result_item_count=0,
        )
        return _err(
            "CONFLICT",
            "Job is already in a terminal state and cannot be cancelled.",
            rule="Refuses with CONFLICT if the job is already in a terminal state",
            job_status=status,
        )

    # Perform transition queued/running -> cancelled (legal per lifecycle)
    job_row = dict(job_row)  # copy for safe mutation
    job_row["status"] = "cancelled"
    job_row["updated_at"] = now_iso
    # finished_at allowed for cancelled and must be >= started_at; set finished_at to now if started_at exists, else keep null.
    # Real systems often set finished_at when cancelled; do so.
    job_row["finished_at"] = now_iso
    if "started_at" not in job_row:
        job_row["started_at"] = None
    # Store cancellation metadata into result_raw for audit without altering schema
    rr = job_row.get("result_raw")
    if not isinstance(rr, dict):
        rr = {}
    rr = dict(rr)
    rr["cancellation"] = {"reason": reason, "requested_at": now_iso}
    job_row["result_raw"] = rr

    jobs_rows[job_index] = job_row
    _persist_rows("jobs.json", jobs_loaded, jobs_rows)

    # Update api key last_used_at
    key_row["last_used_at"] = now_iso
    key_row["updated_at"] = now_iso
    # persist api keys
    for i, r in enumerate(api_keys_rows):
        if isinstance(r, dict) and r.get("id") == api_key_id:
            api_keys_rows[i] = key_row
            break
    _persist_rows("api_keys.json", api_keys_loaded, api_keys_rows)

    # Log success as ok; tool_name should be the underlying job tool_name (enum-valid)
    _append_log(
        workspace_id=workspace_id,
        api_key_id=api_key_id,
        tool_name=job_row.get("tool_name"),
        response_status="ok",
        http_status_code=200,
        job_id_for_log=job_id,
        request_parameters={"job_id": job_id, "reason": reason},
        bytes_downloaded=0,
        result_item_count=0,
    )

    return {"job": job_row}

def list_parsed_results(api_key, job_id=None, engine=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0351000" if __import__("os").path.isdir("./environment_mix/0351000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    # Validate
    if not isinstance(api_key, str) or not api_key.strip():
        logs = _load("request_logs.json")
        log_id = "rlog_" + hashlib.sha256((now_iso + "|list_parsed_results|missing_key").encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": log_id,
            "workspace_id": "unknown",
            "api_key_id": "unknown",
            "job_id": None,
            "tool_name": "google_search_parsed",
            "request_parameters": {"job_id": job_id, "engine": engine, "limit": limit, "cursor": cursor},
            "response_status": "rejected_auth",
            "http_status_code": 401,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "bytes_downloaded": 0,
            "result_item_count": 0,
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", logs)
        return _err("UNAUTHORIZED", "Missing or invalid api_key.")

    if job_id is not None and (not isinstance(job_id, str) or not job_id.strip()):
        return _err("VALIDATION_ERROR", "Invalid job_id.", field="job_id")
    if engine is not None:
        if not isinstance(engine, str) or engine not in ("google", "amazon"):
            return _err("VALIDATION_ERROR", "Invalid engine.", field="engine")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 500.", field="limit")
    if cursor is not None and (not isinstance(cursor, str) or not cursor.strip()):
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # Authenticate
    keys = _load("api_keys.json")
    key_row = None
    for k in keys:
        if k.get("id") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break

    def _write_log(workspace_id, api_key_id, response_status, http_status_code, result_item_count=0):
        logs = _load("request_logs.json")
        log_id = "rlog_" + hashlib.sha256((now_iso + "|list_parsed_results|" + str(api_key_id)).encode("utf-8")).hexdigest()[:24]
        logs.append({
            "id": log_id,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "job_id": None,
            "tool_name": "google_search_parsed",
            "request_parameters": {"job_id": job_id, "engine": engine, "limit": limit, "cursor": cursor},
            "response_status": response_status,
            "http_status_code": http_status_code,
            "latency_ms": max(0, int((time.time() - t0) * 1000)),
            "bytes_downloaded": 0,
            "result_item_count": int(result_item_count or 0),
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("request_logs.json", logs)

    if not key_row or key_row.get("status") != "active":
        wsid = key_row.get("workspace_id") if isinstance(key_row, dict) else "unknown"
        kid = key_row.get("id") if isinstance(key_row, dict) else "unknown"
        _write_log(wsid or "unknown", kid or "unknown", "rejected_auth", 401, 0)
        return _err("UNAUTHORIZED", "Invalid or revoked API key.")

    # Update last_used_at
    for k in keys:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            break
    _save("api_keys.json", keys)

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == key_row.get("workspace_id")), None)
    if not ws or ws.get("status") != "active":
        _write_log(key_row.get("workspace_id") or "unknown", key_row.get("id"), "rejected_auth", 401, 0)
        return _err("UNAUTHORIZED", "Workspace is not active or not found for this API key.")

    # If job_id provided, ensure it exists in workspace (else empty set is ok per contract? description doesn't say)
    # We'll validate existence only for access control: if job_id exists but not in workspace => NOT_FOUND.
    if job_id is not None:
        jobs = _load("jobs.json")
        j = next((x for x in jobs if x.get("id") == job_id), None)
        if j is not None and j.get("workspace_id") != ws.get("id"):
            _write_log(ws.get("id"), key_row.get("id"), "error", 404, 0)
            return _err("NOT_FOUND", "Job not found in this workspace.")

    # Cursor decode: base64url of {"created_at": "...", "id":"..."}
    def _decode_cursor(c):
        try:
            raw = c.encode("utf-8")
            pad = b"=" * ((4 - (len(raw) % 4)) % 4)
            data = base64.urlsafe_b64decode(raw + pad)
            obj = json.loads(data.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            if "created_at" not in obj or "id" not in obj:
                return None
            return obj
        except Exception:
            return None

    anchor = None
    if cursor is not None:
        anchor = _decode_cursor(cursor.strip())
        if anchor is None:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    results = _load("parsed_results.json")

    def _dt_or_min(s):
        if not s:
            return datetime.datetime.min
        try:
            ss = s
            if isinstance(ss, str) and ss.endswith("Z"):
                ss = ss[:-1]
            return datetime.datetime.fromisoformat(ss)
        except Exception:
            return datetime.datetime.min

    filtered = []
    for r in results:
        if r.get("workspace_id") != ws.get("id"):
            continue
        if job_id is not None and r.get("job_id") != job_id:
            continue
        if engine is not None and r.get("engine") != engine:
            continue
        filtered.append(r)

    # Sort newest-first by created_at, then id (deterministic)
    filtered.sort(key=lambda x: (_dt_or_min(x.get("created_at")), x.get("id") or ""), reverse=True)

    if anchor is not None:
        a_dt = _dt_or_min(anchor.get("created_at"))
        a_id = anchor.get("id")
        def _is_after_or_equal(row):
            rdt = _dt_or_min(row.get("created_at"))
            rid = row.get("id") or ""
            if rdt > a_dt:
                return True
            if rdt == a_dt and rid >= a_id:
                return True
            return False
        filtered = [r for r in filtered if not _is_after_or_equal(r)]

    page = filtered[:limit]
    has_more = len(filtered) > len(page)

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"created_at": last.get("created_at"), "id": last.get("id")}
        enc = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = enc

    _write_log(ws.get("id"), key_row.get("id"), "ok", 200, len(page))
    return {
        "data": page,
        "meta": {
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor
        }
    }

def list_request_logs(api_key, response_status=None, tool_name=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0351000" if __import__("os").path.isdir("./environment_mix/0351000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s, field):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field} must be an ISO 8601 date-time string")
        try:
            # Accept trailing Z
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc), None
        except ValueError:
            return None, _err("VALIDATION_ERROR", f"{field} must be a valid ISO 8601 date-time string")

    def _to_dt(value):
        if value is None:
            return None
        if not isinstance(value, str):
            return None
        try:
            vv = value
            if vv.endswith("Z"):
                vv = vv[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(vv)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except ValueError:
            return None

    def _decode_cursor(cur):
        if cur is None:
            return None, None
        if not isinstance(cur, str) or not cur.strip():
            return None, _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"==").decode("utf-8")
            obj = json.loads(raw)
            # Expect {"created_at": "...", "id": "..."} as tiebreakers
            if not isinstance(obj, dict):
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            ca = obj.get("created_at")
            _id = obj.get("id")
            if not isinstance(ca, str) or not isinstance(_id, str) or not ca or not _id:
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            ca_dt = _to_dt(ca)
            if ca_dt is None:
                return None, _err("VALIDATION_ERROR", "cursor is invalid")
            return {"created_at": ca_dt, "id": _id}, None
        except Exception:
            return None, _err("VALIDATION_ERROR", "cursor is invalid")

    def _encode_cursor(created_at_iso, _id):
        payload = json.dumps({"created_at": created_at_iso, "id": _id}, ensure_ascii=False, separators=(",", ":"))
        return base64.urlsafe_b64encode(payload.encode("utf-8")).decode("utf-8").rstrip("=")

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")

    allowed_rs = {"ok", "error", "rejected_quota", "rejected_auth", "rejected_validation"}
    if response_status is not None and response_status not in allowed_rs:
        return _err("VALIDATION_ERROR", "response_status is invalid", allowed=list(sorted(allowed_rs)))

    allowed_tools = {"scrape_as_markdown", "google_search_parsed", "amazon_search_parsed"}
    if tool_name is not None and tool_name not in allowed_tools:
        return _err("VALIDATION_ERROR", "tool_name is invalid", allowed=list(sorted(allowed_tools)))

    if limit is None:
        limit = 100
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500")

    created_after_dt, e = _parse_dt(created_after, "created_after")
    if e:
        return e
    created_before_dt, e = _parse_dt(created_before, "created_before")
    if e:
        return e
    if created_after_dt and created_before_dt and created_after_dt > created_before_dt:
        return _err("VALIDATION_ERROR", "created_after must be <= created_before")

    cur_obj, e = _decode_cursor(cursor)
    if e:
        return e

    # Authenticate: match against api_keys.id OR api_keys.key_hash (client-visible secret) and require active
    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    request_logs = _load("request_logs.json")

    key_row = None
    for r in api_keys:
        if not isinstance(r, dict):
            continue
        if r.get("id") == api_key or r.get("key_hash") == api_key:
            key_row = r
            break

    latency_ms = int((time.time() - t0) * 1000)
    now_iso = _now_iso()

    def _append_log(workspace_id, api_key_id, status, http_code):
        nonlocal request_logs
        # Immutable-ish log; updated_at == created_at
        log_id = None
        try:
            # Generate monotonic-ish id
            log_id = "rl_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        except Exception:
            log_id = "rl_" + str(int(time.time() * 1000))
        row = {
            "id": log_id,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "job_id": None,
            "tool_name": "list_request_logs",
            "request_parameters": {
                "response_status": response_status,
                "tool_name": tool_name,
                "created_after": created_after,
                "created_before": created_before,
                "limit": limit,
                "cursor": cursor,
            },
            "response_status": status,
            "http_status_code": http_code,
            "latency_ms": latency_ms,
            "bytes_downloaded": 0,
            "result_item_count": 0,
            "client_ip": None,
            "user_agent": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        request_logs.append(row)
        _save("request_logs.json", request_logs)

    if key_row is None or key_row.get("status") != "active":
        # Cannot reliably attribute to a workspace without a key; log requirement exists for every call,
        # but schema requires workspace_id/api_key_id. We therefore only log when key resolves.
        return _err("UNAUTHORIZED", "Missing, invalid, or revoked API key")

    workspace_id = key_row.get("workspace_id")
    api_key_id = key_row.get("id")

    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == workspace_id:
            ws = w
            break
    if ws is None:
        # Key references missing workspace => treat as unauthorized (cannot serve request)
        _append_log(workspace_id=workspace_id or "unknown", api_key_id=api_key_id, status="rejected_auth", http_code=401)
        return _err("UNAUTHORIZED", "API key is not associated with a valid workspace")

    # Update last_used_at on key
    try:
        key_row["last_used_at"] = now_iso
        key_row["updated_at"] = now_iso
        _save("api_keys.json", api_keys)
    except Exception:
        # Persist errors should surface as API error object, not raise
        return _err("CONFLICT", "Failed to update API key usage metadata")

    # Filter logs: authenticated workspace only
    logs = [r for r in request_logs if isinstance(r, dict) and r.get("workspace_id") == workspace_id]

    if response_status is not None:
        logs = [r for r in logs if r.get("response_status") == response_status]
    if tool_name is not None:
        logs = [r for r in logs if r.get("tool_name") == tool_name]

    if created_after_dt is not None:
        logs = [r for r in logs if (_to_dt(r.get("created_at")) is not None and _to_dt(r.get("created_at")) >= created_after_dt)]
    if created_before_dt is not None:
        logs = [r for r in logs if (_to_dt(r.get("created_at")) is not None and _to_dt(r.get("created_at")) <= created_before_dt)]

    # Sort newest-first by created_at then id
    def _sort_key(r):
        dt = _to_dt(r.get("created_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))

    logs.sort(key=_sort_key, reverse=True)

    # Cursor pagination: return items strictly "before" the cursor (newest-first)
    if cur_obj is not None:
        ca = cur_obj["created_at"]
        cid = cur_obj["id"]

        def _is_before(r):
            rdt = _to_dt(r.get("created_at"))
            if rdt is None:
                return True
            rid = str(r.get("id") or "")
            # Newest-first: "before" means older created_at, or same created_at but smaller/lexicographically earlier id
            if rdt < ca:
                return True
            if rdt > ca:
                return False
            return rid < cid

        logs = [r for r in logs if _is_before(r)]

    total = len(logs)
    page = logs[:limit]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_created = last.get("created_at")
        last_id = last.get("id")
        if isinstance(last_created, str) and isinstance(last_id, str) and last_created and last_id:
            next_cursor = _encode_cursor(last_created, last_id)

    # Log this tool invocation as ok
    _append_log(workspace_id=workspace_id, api_key_id=api_key_id, status="ok", http_code=200)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }
